import { db } from './db'
import dataset from './data/dataset-2024.json'
import type { Data } from './types'

/**
 * Demo data: the documented 2024 dataset (docs/dataset-2024.md), generated by
 * scripts/generate-dataset-2024.ts. Prices are estimates in kyat.
 */
export const DEMO_DATA = dataset as Data

export async function seedIfEmpty() {
  if ((await db.packages.count()) > 0) return
  await db.transaction('rw', db.tables, async () => {
    await db.packages.bulkAdd(DEMO_DATA.packages)
    await db.customers.bulkAdd(DEMO_DATA.customers)
    await db.bookings.bulkAdd(DEMO_DATA.bookings)
    await db.visas.bulkAdd(DEMO_DATA.visas)
    await db.passports.bulkAdd(DEMO_DATA.passports)
    await db.tickets.bulkAdd(DEMO_DATA.tickets)
  })
}
